import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public int calculate(String s) {
        Deque<Integer> outerSums = new ArrayDeque<>();
        Deque<Integer> outerSigns = new ArrayDeque<>();
        int sum = 0;
        int sign = 1;
        int number = 0;
        for (int index = 0; index < s.length(); index++) {
            char current = s.charAt(index);
            if (Character.isDigit(current)) {
                number = number * 10 + current - '0';
            } else if (current == '+') {
                sum += sign * number;
                number = 0;
                sign = 1;
            } else if (current == '-') {
                sum += sign * number;
                number = 0;
                sign = -1;
            } else if (current == '(') {
                outerSums.push(sum);
                outerSigns.push(sign);
                sum = 0;
                sign = 1;
                number = 0;
            } else if (current == ')') {
                sum += sign * number;
                number = 0;
                sum = outerSums.pop() + outerSigns.pop() * sum;
                sign = 1;
            }
        }
        return sum + sign * number;
    }
}

