import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public int calculate(String s) {
        Deque<Integer> signContext = new ArrayDeque<>();
        signContext.push(1);
        int result = 0;
        int sign = 1;
        int number = 0;
        for (int index = 0; index < s.length(); index++) {
            char current = s.charAt(index);
            if (Character.isDigit(current)) {
                number = number * 10 + current - '0';
            } else if (current == '+' || current == '-') {
                result += sign * number;
                number = 0;
                sign = signContext.peek() * (current == '+' ? 1 : -1);
            } else if (current == '(') {
                signContext.push(sign);
            } else if (current == ')') {
                result += sign * number;
                number = 0;
                signContext.pop();
                sign = signContext.peek();
            }
        }
        return result + sign * number;
    }
}
